 rows=[r for r in read(use(R/'data/data_manifest.json'))['records']if r['split']in SPLITS];index={(r['episode_id'],r['step']):r for r in read(use(R/'data/features/index.json'))['items']if r['split']in SPLITS};by=collections.defaultdict(list)
