   final=dict(np.load(use(rr[0]['obs_before']if t==0 else r['obs_after'])));assert frames[-1].keys()==final.keys();assert all(np.array_equal(frames[-1][k],final[k])for k in final);assert np.allclose(frames[-1]['robot_obs'][:3],info['robot_info']['tcp_pos'],atol=1e-12)
   for color in COLORS:assert np.array_equal(target['continuous']['objects'][color]['position_m'],info['scene_info']['movable_objects']['block_'+color]['current_pos'])
   n=0;kind='root';localsteps=[];reused=False
   if t:
    res=read(use(Path(r['labels_path']).parent/'result_private.json'));controls=read(use(Path(r['labels_path']).parent/'controls.json'));trace=json.loads(gzip.decompress(use(Path(r['labels_path']).parent/'trace_private.json.gz').read_bytes()));n=lab['control_samples_including_start']-1;assert len(controls)==len(trace)==n;assert [c['step']for c in controls]==list(range(1,n+1));kind='success'if lab['success']else'failed'if n else'refused'
    if n:
     assert n>=4
